from pathlib import Path
from collections.abc import Sequence
import cecpy
from cecpy.bindings import (
    _Evaluator,
    CECEdition,
    benchmark_problem_num,
    benchmark_valid_dimensions,
)

_DEFAULT_BENCHMARK_DATA_DIR = Path(cecpy.__file__).parent / "data"


def problem_optimum_value(edition: CECEdition, problem_number: int):
    match edition:
        case CECEdition.CEC2013:
            return (
                problem_number * 100 - 1500
                if problem_number <= 14
                else problem_number * 100 - 1400
            )
        case CECEdition.CEC2014 | CECEdition.CEC2017:
            return problem_number * 100


class CECEvaluator:
    """
    IEEE CEC benchmark evaluator object

    This class represents IEEE CEC benchmark evaluator, i.e., object which loads benchmark data
    (mainly matrices and vectors for geometric transformations), and provides overoladed call
    operator to evaluate given input (always row-major matrices where column represents working
    point).

    """

    def __init__(
        self,
        edition: CECEdition,
        dimensions: Sequence[int],
        benchmark_data_storage: Path = _DEFAULT_BENCHMARK_DATA_DIR,
    ):

        self._data_storage = benchmark_data_storage
        self._edition = edition
        self._dimensions = dimensions
        self._evaluator = _Evaluator(
            self._edition, self._dimensions, self._data_storage
        )

    def __call__(self, problem_number: int, input: Sequence[float]):
        """
        Evaluates given input for given benchmark problem.
        To obtain available benchmark problem for given IEEE CEC
        edition, see `benchmark_problem_num` helper function.
        """
        return self._evaluator.evaluate(problem_number, input)

    @property
    def edition(self) -> CECEdition:
        return self._edition

    @property
    def dimensions(self) -> list[int]:
        return self._dimensions
